SELECT channel, DATE_TRUNC('MONTH', order_date) AS order_month, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, MIN(shipping_fee) AS min_shipping_fee, SUM(shipping_fee) AS total_shipping_fee FROM orders WHERE status NOT IN ('RETURNED', 'SHIPPED', 'PENDING') AND store_id IS NOT NULL AND status IN ('CANCELLED', 'SHIPPED', 'COMPLETED') GROUP BY channel, DATE_TRUNC('MONTH', order_date) ORDER BY channel
